-- 아이템 하단부 툴팁을 표시하기 위해 검색테이블 단일화
for k,v in pairs(NuguDropEtc) do
	-- 던전셋은 원래 정보를 보여줘야 하므로 툴팁에서 제외
	if (not string.find(v[2], "던전셋")) then
		NuguDrop[k]=v;
	end
end